# Assertion-reason
_CORRECT = re.compile(r"^Correct! A is (?:true|false): (.*) R is (?:true|false): (.*)$")
def ar(key, a, r, wa, wr, ex):
    it = item(key)
    a_en, r_en = it["question"].replace("**Assertion (A):** ", "").split("\n\n**Reason (R):** ")
    wa_en, wr_en = _CORRECT.match(it["option_feedback"][it["correct_index"]]).groups()
    (a_hi, a_gu), (r_hi, r_gu) = fill(a_en, *a), fill(r_en, *r)
    (wa_hi, wa_gu), (wr_hi, wr_gu), (ex_hi, ex_gu) = fill(wa_en, *wa), fill(wr_en, *wr), fill(it["explanation"], *ex)
    return (a_hi, r_hi, a_gu, r_gu, wa_hi, wr_hi, wa_gu, wr_gu, ex_hi, ex_gu)
